import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sc.common.common import LocalBasicPage


class ConfirmationModal(LocalBasicPage):
    _MODAL_XPATH = '//*[@class="modal-panel"]'

    def __init__(self, driver, download_checker=None):
        super(ConfirmationModal, self).__init__(driver, download_checker)

    def confirm(self):
        """
        Clicks confirm button in selenium_sbts confirmation modal
        """
        pass

    def cancel(self):
        """
        Clicks cancel button in selenium_sbts confirmation modal
        """
        pass

    def wait_until_modal_appear(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)


class LegalInformationModal(ConfirmationModal):
    _ACCEPT_BUTTON = '//*[@class="modal-panel"]//button[contains(text(), "Accept")]'

    def __init__(self, driver):
        super(LegalInformationModal, self).__init__(driver)

    def wait_until_legal_info_modal_appear(self, timeout=60):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
        except TimeoutException:
            logging.info("not found legal info modal")

    def accept(self):
        self.click_enabled_element((By.XPATH, self._ACCEPT_BUTTON))


class OverwirteRecentEditedConfigurationModal(ConfirmationModal):
    _OVERWRITE_BUTTON = '//*[@class="modal-panel"]//button[contains(text(), "Overwrite")]'

    def __init__(self, driver):
        super(OverwirteRecentEditedConfigurationModal, self).__init__(driver)

    def wait_until_overwrite_conf_modal_appear(self, timeout=60):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
            return True
        except TimeoutException:
            logging.info("not found overwrite conf modal")
            return False

    def overwrite(self):
        self.click_enabled_element((By.XPATH, self._OVERWRITE_BUTTON))


class ValidationErrorOccurred(ConfirmationModal):
    _MODAL_XPATH = '//*[@class="modal-panel"]//div[contains(text(), "errors")]'
    _CLOSE_BUTTON = '//*[@class="modal-panel"]//button[contains(text(), "Close")]'

    def __init__(self, driver):
        super(ValidationErrorOccurred, self).__init__(driver)

    def wait_until_validation_error_modal_appear(self, timeout=60):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
            return True
        except TimeoutException:
            logging.info("no found validation errors modal found")
            return False

    def close(self):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON))
